/**
 * tracker.js — ByteTrack v3, ported from src/tracker/byte_tracker.py.
 * Same stages, thresholds, tentative-track logic, class-group gating and
 * unique counting; web/tests/tracker.test.mjs checks frame-by-frame parity
 * against the Python implementation (tests/fixtures/tracker_golden.json,
 * generated by scripts/dev/make_tracker_golden.py).
 */
import { GROUP_ORDER, groupOf } from './classes.js';
import { KalmanFilterXYAH, tlbrToXyah, xyahToTlbr } from './kalman.js';
import { fuseScore, gateGroups, iouCost, iouMatrix, linearAssignment } from './matching.js';

/** Same snake_case keys and values as configs/tracker.yaml (the parity test pins this). */
export const DEFAULT_CONFIG = {
  track_high: 0.4, track_low: 0.1, new_track: 0.5, match_thresh: 0.8, second_match_thresh: 0.5,
  unconfirmed_match_thresh: 0.7, max_time_lost: 30, fuse_score: true, class_vote_window: 30,
  min_hits_for_count: 3,
};
const State = { NEW: 0, TRACKED: 1, LOST: 2, REMOVED: 3 };

/** Round half to even, like Python's round(); Math.round rounds halves up and would drift from Python. */
export function pyRound(x) {
  const f = Math.floor(x);
  const diff = x - f;
  if (diff < 0.5) return f;
  if (diff > 0.5) return f + 1;
  return f % 2 === 0 ? f : f + 1;
}

export class STrack {
  constructor(det, voteWindow = 30, historyLen = 60) {
    this.initTlbr = det.tlbr.slice();
    this.mean = null; this.cov = null;
    this.trackId = 0; this.state = State.NEW; this.isActivated = false;
    this.score = det.score; this.group = groupOf(det.cls);
    this.votes = [det.cls]; this.voteWindow = voteWindow;
    this.history = []; this.historyLen = historyLen;
    this.frameId = 0; this.startFrame = 0; this.hits = 0;
  }
  get tlbr() { return this.mean ? xyahToTlbr(this.mean) : this.initTlbr.slice(); }
  /** Majority vote over the recent matched classes; ties go to the most recent class. */
  get cls() {
    const counts = new Map();
    for (const c of this.votes) counts.set(c, (counts.get(c) || 0) + 1);
    const best = Math.max(...counts.values());
    for (let i = this.votes.length - 1; i >= 0; i--) if (counts.get(this.votes[i]) === best) return this.votes[i];
    return undefined; // unreachable: some vote always attains the maximum count
  }
  record() {
    const [x1, y1, x2, y2] = this.tlbr;
    this.history.push([(x1 + x2) / 2, (y1 + y2) / 2]);
    if (this.history.length > this.historyLen) this.history.shift();
  }
  activate(kf, frameId) {
    ({ mean: this.mean, cov: this.cov } = kf.initiate(tlbrToXyah(this.initTlbr)));
    this.state = State.TRACKED; this.frameId = this.startFrame = frameId; this.hits = 1;
    this.record();
  }
  confirm(id) { this.trackId = id; this.isActivated = true; }
  predict(kf) {
    const m = this.mean.slice();
    if (this.state !== State.TRACKED) m[7] = 0;
    ({ mean: this.mean, cov: this.cov } = kf.predict(m, this.cov));
  }
  update(kf, det, frameId) {
    ({ mean: this.mean, cov: this.cov } = kf.update(this.mean, this.cov, tlbrToXyah(det.tlbr)));
    this.score = det.score;
    this.votes.push(det.cls);
    if (this.votes.length > this.voteWindow) this.votes.shift();
    this.frameId = frameId; this.hits += 1; this.state = State.TRACKED;
    this.record();
  }
  applyWarp(w) {
    const [[a, b, tx], [c, d, ty]] = w;
    const Tm = Array.from({ length: 8 }, (_, i) => Array.from({ length: 8 }, (_, j) => (i === j ? 1 : 0)));
    Tm[0][0] = a; Tm[0][1] = b; Tm[1][0] = c; Tm[1][1] = d;
    Tm[4][4] = a; Tm[4][5] = b; Tm[5][4] = c; Tm[5][5] = d;
    const m = Tm.map((row) => row.reduce((s, v, j) => s + v * this.mean[j], 0));
    m[0] += tx; m[1] += ty;
    const TP = Tm.map((row) => this.cov[0].map((_, j) => row.reduce((s, v, k) => s + v * this.cov[k][j], 0)));
    this.cov = TP.map((row) => Tm.map((trow) => row.reduce((s, v, k) => s + v * trow[k], 0)));
    this.mean = m;
  }
}

const joint = (a, b) => { const s = new Set(a); return a.concat(b.filter((t) => !s.has(t))); };
const without = (a, b) => { const s = new Set(b); return a.filter((t) => !s.has(t)); };

function removeDuplicates(tracked, lost) {
  if (!tracked.length || !lost.length) return [tracked, lost];
  const iou = iouMatrix(tracked.map((t) => t.tlbr), lost.map((t) => t.tlbr));
  const dupT = new Set(), dupL = new Set();
  iou.forEach((row, p) => row.forEach((v, q) => {
    if (v <= 0.85 || tracked[p].group !== lost[q].group) return;
    const ageT = tracked[p].frameId - tracked[p].startFrame, ageL = lost[q].frameId - lost[q].startFrame;
    if (ageT > ageL) dupL.add(q); else dupT.add(p);
  }));
  return [tracked.filter((_, i) => !dupT.has(i)), lost.filter((_, i) => !dupL.has(i))];
}

export class ByteTracker {
  constructor(config = DEFAULT_CONFIG, frameRate = 30) {
    this.cfg = { ...DEFAULT_CONFIG, ...config };
    this.maxTimeLost = pyRound(this.cfg.max_time_lost * frameRate / 30);
    this.kf = new KalmanFilterXYAH();
    this.reset();
  }
  reset() { this.tracked = []; this.lost = []; this.frameId = 0; this.lastId = 0; this.counted = new Map(); }
  get totalIds() { return this.lastId; }
  nextId() { this.lastId += 1; return this.lastId; }
  uniqueCounts() {
    const out = Object.fromEntries(GROUP_ORDER.map((g) => [g, 0]));
    for (const g of this.counted.values()) out[g] += 1;
    return out;
  }
  cost(tracks, dets, fuse) {
    if (!tracks.length || !dets.length) return tracks.map(() => []);
    let c = iouCost(tracks.map((t) => t.tlbr), dets.map((d) => d.tlbr));
    if (fuse) c = fuseScore(c, dets.map((d) => d.score));
    return gateGroups(c, tracks.map((t) => t.group), dets.map((d) => d.group));
  }

  /** dets: Array<[x1, y1, x2, y2, score, cls]>; warp: [[a,b,tx],[c,d,ty]] | null */
  update(dets, warp = null) {
    this.frameId += 1;
    const cfg = this.cfg;
    // Degenerate boxes (non-positive width/height, or NaN) are dropped, exactly like the Python
    // _to_detections: the Kalman filter works in (cx, cy, aspect, height) space and a
    // non-positive height makes its innovation covariance singular.
    const detections = dets.filter((d) => d[2] > d[0] && d[3] > d[1] && d[4] >= cfg.track_low)
      .map((d) => ({ tlbr: d.slice(0, 4), score: d[4], cls: d[5], group: groupOf(d[5]) }));
    const high = detections.filter((d) => d.score >= cfg.track_high);
    const low = detections.filter((d) => d.score < cfg.track_high);

    const unconfirmed = this.tracked.filter((t) => !t.isActivated);
    const pool = joint(this.tracked.filter((t) => t.isActivated), this.lost);
    for (const t of [...pool, ...unconfirmed]) { t.predict(this.kf); if (warp) t.applyWarp(warp); }

    const activated = [], refound = [], lostNow = [], removed = [];

    // Stage 1: high-score detections vs confirmed tracked + lost tracks.
    const s1 = linearAssignment(this.cost(pool, high, cfg.fuse_score), cfg.match_thresh, high.length);
    for (const [ti, di] of s1.matches) {
      const t = pool[ti], wasTracked = t.state === State.TRACKED;
      t.update(this.kf, high[di], this.frameId);
      (wasTracked ? activated : refound).push(t);
    }

    // Stage 2: low-score detections keep still-unmatched *tracked* tracks alive.
    const remaining = s1.unmatchedRows.map((i) => pool[i]).filter((t) => t.state === State.TRACKED);
    const s2 = linearAssignment(this.cost(remaining, low, false), cfg.second_match_thresh, low.length);
    for (const [ti, di] of s2.matches) { remaining[ti].update(this.kf, low[di], this.frameId); activated.push(remaining[ti]); }
    for (const i of s2.unmatchedRows) { remaining[i].state = State.LOST; lostNow.push(remaining[i]); }

    // Stage 3: tentative tracks are confirmed by a second match, else removed.
    const leftover = s1.unmatchedCols.map((i) => high[i]);
    const s3 = linearAssignment(this.cost(unconfirmed, leftover, cfg.fuse_score), cfg.unconfirmed_match_thresh, leftover.length);
    for (const [ti, di] of s3.matches) {
      const t = unconfirmed[ti];
      t.update(this.kf, leftover[di], this.frameId);
      t.confirm(this.nextId());
      activated.push(t);
    }
    for (const i of s3.unmatchedRows) { unconfirmed[i].state = State.REMOVED; removed.push(unconfirmed[i]); }

    // New tentative tracks (confirmed immediately on the very first frame).
    for (const i of s3.unmatchedCols) {
      const d = leftover[i];
      if (d.score < cfg.new_track) continue;
      const t = new STrack(d, cfg.class_vote_window);
      t.activate(this.kf, this.frameId);
      if (this.frameId === 1) t.confirm(this.nextId());
      activated.push(t);
    }

    for (const t of this.lost) if (this.frameId - t.frameId > this.maxTimeLost) { t.state = State.REMOVED; removed.push(t); }

    this.tracked = this.tracked.filter((t) => t.state === State.TRACKED);
    this.tracked = joint(joint(this.tracked, activated), refound);
    this.lost = without(this.lost, this.tracked).concat(lostNow);
    this.lost = without(this.lost, removed);
    [this.tracked, this.lost] = removeDuplicates(this.tracked, this.lost);

    for (const t of this.tracked)
      if (t.isActivated && t.hits >= cfg.min_hits_for_count && !this.counted.has(t.trackId)) this.counted.set(t.trackId, t.group);
    return this.tracked.filter((t) => t.isActivated);
  }
}
